const traitNames=['creatividad','curiosidad','analisis','empatia','iniciativa','autonomia','sensibilidad','intensidad','humor','prudencia','sinceridad','afecto','reciprocidad','conexion','espontaneidad','seguridad','confianza','adaptacion','constancia','exclusividad','atraccion','orgullo','resolucion','sociabilidad','observacion','timidez','limites','intuicion','perfeccionismo','impulsividad','lealtad','inseguridad','validacion','expresividad','cuidado','contacto','regulacion','ocultacion','humildad','novedad','celos','posesividad','monogamia','apertura_relacional','compersion','negociacion','autocontrol','libido','curiosidad_intima','novedad_intima','conexion_intima','seguridad_intima','apertura_intima','limites_intimos','imaginacion_intima','receptividad_intima','iniciativa_intima','comunicacion_intima','privacidad','coqueteo','introspeccion'];
const base=Object.fromEntries(traitNames.map(x=>[x,50]));

const LEGACY_USERS_KEY='private-life-users';
const LEGACY_SESSION_KEY='private-life-session';
const saveKey=user=>`private-life-save:${String(user||'').toLowerCase()}`;
async function apiRequest(url,options={}){const response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.error||'Error de conexión');return data}
async function trackPhone(state,event=null){try{await fetch('/api/phone/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state,event}),keepalive:true})}catch{}}
function readLegacyUsers(){try{return JSON.parse(localStorage.getItem(LEGACY_USERS_KEY)||'{}')}catch{return {}}}
async function digestLegacyPassword(password,salt){const bytes=new TextEncoder().encode(`${salt}:${password}`);const hash=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('')}
async function verifiedLegacyAccount(username,password){const key=String(username||'').trim().toLowerCase(),users=readLegacyUsers(),account=users[key];if(!account?.salt||!account?.passwordHash)return null;const hash=await digestLegacyPassword(password,account.salt);return hash===account.passwordHash?{key,account,users}:null}
function clearLegacyAccount(key,users){try{delete users[key];if(Object.keys(users).length)localStorage.setItem(LEGACY_USERS_KEY,JSON.stringify(users));else localStorage.removeItem(LEGACY_USERS_KEY);if(localStorage.getItem(LEGACY_SESSION_KEY)===key)localStorage.removeItem(LEGACY_SESSION_KEY)}catch{}}

function buildProfile(answers,free){const s={...base};answers.forEach((v,i)=>{(questions[i]?.tags[v]||[]).forEach(t=>s[t]=(s[t]||50)+7)});Object.keys(s).forEach(k=>s[k]=Math.max(0,Math.min(100,s[k])));if(free.trim().length>30){s.creatividad=Math.min(100,s.creatividad+4);s.curiosidad=Math.min(100,s.curiosidad+4)}return s}
const HISTORY_LIMIT=60000;
function conversationNoise(line){
 const body=line.replace(/^[^:\n]{1,80}:\s*/,'').trim();
 return /^(?:<\s*)?(?:media|multimedia|image|imagen|photo|foto|video|vídeo|audio|sticker|gif|document|documento|archivo)(?:\s+(?:omitted|omitid[oa]|no incluido|excluido))?(?:\s*>)?$/i.test(body)
  || /^(?:this message was deleted|you deleted this message|message deleted|se eliminó este mensaje|eliminaste este mensaje|mensaje eliminado)\.?$/i.test(body)
  || /^(?:missed (?:voice|video) call|llamada (?:de voz|de vídeo|de video) perdida)\.?$/i.test(body)
  || /^(?:messages and calls are end-to-end encrypted.*|los mensajes y las llamadas están cifrados de extremo a extremo.*)$/i.test(body);
}
function optimizeConversationText(input){
 let text=String(input??'').replace(/\r\n?/g,'\n').replace(/[\u200e\u200f\u202a-\u202e\u2066-\u2069\ufeff]/g,'').replace(/[\u00a0\u202f]/g,' ');
 const useful=[];
 for(const raw of text.split('\n')){
  let line=raw.trim();
  if(!line)continue;
  line=line
   .replace(/^\[\s*(?:\d{1,4}[\/.-]){2}\d{1,4}\s*,?\s*\d{1,2}:\d{2}(?::\d{2})?\s*(?:a\.?\s*m\.?|p\.?\s*m\.?|am|pm)?\s*\]\s*/i,'')
   .replace(/^(?:\d{1,4}[\/.-]){2}\d{1,4}\s*,?\s*\d{1,2}:\d{2}(?::\d{2})?\s*(?:a\.?\s*m\.?|p\.?\s*m\.?|am|pm)?\s*[-–—]\s*/i,'')
   .trim();
  if(!line||conversationNoise(line))continue;
  line=line.replace(/\bhttps?:\/\/\S+/gi,'[enlace]').replace(/\bwww\.\S+/gi,'[enlace]');
  useful.push(line);
 }
 return useful.join('\n').slice(0,HISTORY_LIMIT);
}
function conversationSignals(text){const clean=optimizeConversationText(text).trim();if(!clean)return null;const lines=clean.split(/\n+/).filter(Boolean);const words=clean.split(/\s+/).filter(Boolean);return{sampleCharacters:clean.length,lines:lines.length,averageWordsPerLine:Math.round(words.length/Math.max(lines.length,1)),questionMarks:(clean.match(/\?/g)||[]).length,exclamations:(clean.match(/!/g)||[]).length,laughter:(clean.match(/jaj|haha|jeje|lol/gi)||[]).length,emojiLike:(clean.match(/[😀-🙏🌀-🫿]/gu)||[]).length,status:'local_signals_ready_ai_pending'}}
function hiddenAnalysis(photo,conversation){const cleanConversation=optimizeConversationText(conversation);return{appearance:{status:photo?'pending_ai':'not_provided',perceivedAttractiveness:null,presentation:null,visualStyle:null},communication:{status:cleanConversation?'pending_ai':'not_provided',signals:conversationSignals(cleanConversation),warmth:null,humor:null,directness:null,expressiveness:null,languageStyle:null},note:'Las percepciones sociales serán contextuales por personaje. La orientación o identidad sexual no se inferirá de fotos ni conversaciones: se respetará lo declarado por el jugador.'}}

const DEFAULT_REMOVABLE_PHONE_APPS=['instagram','whatsapp','facebook','private-life','phone','messages','safari','music'];
const PHONE_APP_STATE_VERSION=1;

function normalizeAppStore(value={},datingApps={}){
 const installed=new Set(Array.isArray(value?.installed)?value.installed:[]);
 if(Number(value?.managedAppsVersion||0)<PHONE_APP_STATE_VERSION){
   for(const id of DEFAULT_REMOVABLE_PHONE_APPS)installed.add(id);
 }
 if(datingApps?.tinder)installed.add('tinder');
 if(datingApps?.grindr)installed.add('grindr');
 return {installed:[...installed],history:Array.isArray(value?.history)?value.history.slice(0,120):[],managedAppsVersion:PHONE_APP_STATE_VERSION};
}

