 async function confirm(){const cleanDating={tinder:false,grindr:false},normalizedStore=normalizeAppStore(appStore,cleanDating),digitalContext=buildAppNarrativeContext(normalizedStore.installed),nextHidden={...(hidden||{}),digital:digitalContext},save={identity,sources,datingApps:cleanDating,profile,hidden:nextHidden,free,appStore:normalizedStore,digitalContext};setDatingApps(cleanDating);setAppStore(normalizedStore);setHidden(nextHidden);try{await persistGame(save);localStorage.removeItem(saveKey(authUser))}catch{try{localStorage.setItem(saveKey(authUser),JSON.stringify(save))}catch{}}setStep('location')}
