 function photoPicked(file){if(!file)return;if(!String(file.type||'').startsWith('image/')){setAuthError('Selecciona un archivo de imagen válido.');return}const reader=new FileReader();reader.onload=()=>setPhotoEditorSrc(String(reader.result||''));reader.readAsDataURL(file)}
 function applyHistoryText(raw){const original=String(raw||'');const optimized=optimizeConversationText(original);setSources(s=>({...s,conversation:optimized}));setHistoryInfo({before:original.length,after:optimized.length})}
 function historyPasted(e){const pasted=e.clipboardData?.getData('text/plain');if(!pasted)return;e.preventDefault();const current=sources.conversation;const start=e.currentTarget.selectionStart??current.length;const end=e.currentTarget.selectionEnd??start;applyHistoryText(current.slice(0,start)+pasted+current.slice(end))}
